import { z } from 'zod';
import pins from './pins.json';
import { type AddonContributions, addonContributionsSchema } from './contribution';

/**
 * The add-ons this build needs, generated by `scripts/build-addons.mjs`.
 *
 * Each entry names the **content identity** of the add-on the build was made
 * against (a digest of its sources, not a hand-written version), the
 * `apiVersion` it expects, and everything it contributes - its tools and the
 * catalogue entries of its skills. A published catalogue may hold many
 * identities at once, and an installed add-on of another identity is never used
 * - the pinned one is downloaded and the older one deleted.
 *
 * This is the **only** run-time source of an add-on's contributions: the
 * application advertises its tools and skills from here, before the add-on has
 * ever been downloaded, and reads their names, schemas and billets as data.
 */

/** One add-on's id: lower-case letters, digits and hyphens. */
export const ADDON_ID_PATTERN = /^[a-z][a-z0-9-]{0,63}$/;

export const addonPinsSchema = z.record(
  z.string().regex(ADDON_ID_PATTERN),
  z
    .object({
      identity: z.string().regex(/^[0-9a-f]{16}$/),
      apiVersion: z.number().int().positive(),
      contributions: addonContributionsSchema,
    })
    .strict(),
);

export type AddonPins = z.infer<typeof addonPinsSchema>;

export interface AddonPin {
  readonly identity: string;
  readonly apiVersion: number;
  readonly contributions: AddonContributions;
}

/**
 * The pins this build ships. Parsed once, at module load: a malformed generated
 * file is a build fault and must fail loudly rather than silently install
 * nothing.
 */
export const addonPins: AddonPins = addonPinsSchema.parse(pins);

export function pinFor(id: string): AddonPin | undefined {
  return addonPins[id];
}

/** Every pinned add-on id, sorted, so iteration order is deterministic. */
export function pinnedAddonIds(): readonly string[] {
  return Object.keys(addonPins).sort();
}
